// records its last change time by workspace key on close, and the next store with the same key
// subscribes with startAfter — the server replays the gap (inclusive, as upserts) through the
// subscription, so per-record consumers are patched without refetching.

export type ActionsState = {
  /**
   * 'checking' until the subscription is registered and the last pending page has loaded;
   * 'error' if either failed (`pending` keeps whatever was gathered).
   */
  status: 'checking' | 'ready' | 'error'

  /** Pending-review records found so far, oldest first (createdAt, then id). */
  pending: readonly ActionLogEntry[]
}

type Store = {
  // Immutable object handed to useSyncExternalStore; rebuilt from the staged fields on commit.
  snapshot: ActionsState
  stagedPending: Map<number, ActionLogEntry>
  // Records delivered on the live subscription (only — paged records are not entries), retained
  // for useActionEntries' mount-time replay.
  stagedEntries: Map<number, ActionLogEntry>
  refCount: number
  listeners: Set<() => void>
  entryListeners: Set<(record: ActionLogEntry) => void>
  subscription: RpcStub<{}> | null
  generation: number
  notifyScheduled: boolean
  // Max change time (actionChangeTime, the server's index key) received this session, live or
  // paged. Every change a settled session missed has change time ≥ its disconnect time ≥ this
  // max, so an inclusive startAfter replay from it covers the gap.
  lastChanged: Date | undefined
  resumed: boolean
}

const EMPTY_STATE: ActionsState = {
  status: 'checking',
  pending: [],
}

const stores = new WeakMap<RpcStub<Overseer>, Store>()

const storeKeys = new WeakMap<RpcStub<Overseer>, string>()
// Never deleted: a failed later session leaves the last good watermark in place, and resuming
// from an older watermark just replays more.
const watermarks = new Map<string, Date>()

/**
 * Give the stub a stable workspace identity so its store parks a resume watermark on close and
 * a later stub with the same key replays the gap. Unlinked stubs always open blind.
 */
export function linkActionLog(overseer: RpcStub<Overseer>, key: string): void {
  storeKeys.set(overseer, key)
}

/**
 * Whether the stub's store subscribed with startAfter — its gap is replayed as entries.
 * Consumers may trust this without a failure path: a resumed session that later errors surfaces
 * as store status 'error' and never parks a watermark, so the next stub swap replays its entire
 * gap from the last good one.
 */
export function actionLogResumed(overseer: RpcStub<Overseer> | null): boolean {
  return (overseer && stores.get(overseer)?.resumed) ?? false
}

function getStore(overseer: RpcStub<Overseer>): Store {
  let store = stores.get(overseer)
  if (!store) {
    store = {
      snapshot: EMPTY_STATE,
      stagedPending: new Map(),
      stagedEntries: new Map(),
      refCount: 0,
      listeners: new Set(),
      entryListeners: new Set(),
      subscription: null,
      generation: 0,
      notifyScheduled: false,
      lastChanged: undefined,
      resumed: false,
    }
    stores.set(overseer, store)
  }
  return store
}

function commit(store: Store, status: ActionsState['status'] = store.snapshot.status): void {
  // Entries arrive in ascending id order, so this sort is near-free at pending-count scale.
  const pending = [...store.stagedPending.values()].toSorted((a, b) =>
    a.createdAt.getTime() - b.createdAt.getTime() || a.id - b.id)
  store.snapshot = { status, pending }
  for (const listener of store.listeners) listener()
}

// Coalesce bursts of entries into one snapshot per frame. Status transitions commit synchronously
// instead (see openSubscription) so a throttled background tab still settles.
function scheduleNotify(store: Store) {
  if (store.notifyScheduled) return
  store.notifyScheduled = true

  window.requestAnimationFrame(() => {
    store.notifyScheduled = false
    commit(store)
  })
}

// Bumps the generation (orphaning any in-flight callbacks) and clears the staged session state.
function resetSession(store: Store): number {
  store.generation++
  store.stagedPending = new Map()
  store.stagedEntries = new Map()
  store.snapshot = EMPTY_STATE
  store.lastChanged = undefined
  store.resumed = false
  return store.generation
}

function trackChange(store: Store, record: ActionLogEntry): void {
  const changed = actionChangeTime(record)
  if (!store.lastChanged || changed > store.lastChanged) store.lastChanged = changed
}

function openSubscription(overseer: RpcStub<Overseer>, store: Store) {
  const generation = resetSession(store)
  const key = storeKeys.get(overseer)
  const startAfter = key === undefined ? undefined : watermarks.get(key)
  store.resumed = startAfter !== undefined

  class ActionsSubscriberImpl extends RpcTarget implements ActionsSubscriber {
    entry(record: ActionLogEntry): void {
      if (store.generation !== generation) return
      trackChange(store, record)
      store.stagedEntries.set(record.id, record)
      let pendingChanged: boolean
      if (record.state === 'pending') {
        store.stagedPending.set(record.id, record)
        pendingChanged = true
      } else {
        pendingChanged = store.stagedPending.delete(record.id)
      }
      // Entries that never touch the pending set (observations, hook events) don't need a
      // re-sorted snapshot or a consumer re-render.
      if (pendingChanged) scheduleNotify(store)
      for (const listener of store.entryListeners) {
        try {
          listener(record)
        } catch (err) {
          console.error('Action entry listener failed:', err)
        }
      }
    }

    // Settledness is signalled by the pending page loop draining, not by the subscription.
    ready(): void {}
  }
  const subscriber = new ActionsSubscriberImpl() as unknown as RpcStub<ActionsSubscriber>

  let failed = false
  const fail = (error: unknown) => {
    if (store.generation !== generation) return
    console.error('Failed to load pending actions:', error)
    // Deliberately also downgrades an already-'ready' store: the pages can drain before the
    // subscribe call's return trip fails, and a store with a dead live stream must not present
    // as settled.
    failed = true
    commit(store, 'error')
  }

  // Initiated first — the page loop below relies on capnweb e-order having registered the
  // subscriber server-side before the first page reads. With a watermark the server also replays
  // the gap (everything changed at/after it, as upserts) ahead of the pages.
  const subscribed = startAfter
    ? overseer.subscribeToActions(subscriber, startAfter)
    : overseer.subscribeToActions(subscriber)
  subscribed.then(sub => {
    if (store.generation !== generation) {
      sub[Symbol.dispose]()
      return
    }
    store.subscription = sub
  }, fail)

  // One page in flight at a time. Records created mid-paging are live-only (their ids are above
  // page 1's snapshot bound), so the fold only has to resolve one conflict class: a page's stale
  // copy of a record the subscription already delivered — the subscription's copy (in any state)
  // is newer by definition, so a record resolved live is never re-marked pending by a page that
  // predates the resolution.
  ;(async () => {
    let beforeId: number | undefined
    do {
      const page = await overseer.listActions({ filter: 'pending', beforeId })
      if (store.generation !== generation) return
      for (const record of page.entries) {
        trackChange(store, record)
        if (!store.stagedEntries.has(record.id)) store.stagedPending.set(record.id, record)
      }
      beforeId = page.nextBeforeId
      scheduleNotify(store)
    } while (beforeId !== undefined)
    // Synchronous commit (not scheduleNotify) so a throttled background tab still settles. A
    // subscribe failure is sticky: pages draining afterwards must not upgrade a store whose live
    // stream is dead back to 'ready'.
    commit(store, failed ? 'error' : 'ready')
  })().catch(fail)
}

function closeSubscription(overseer: RpcStub<Overseer>, store: Store) {
  const key = storeKeys.get(overseer)
  // Only a cleanly settled session sets the watermark: pages drained AND subscribe resolved. The
  // second condition is load-bearing — a page-only watermark is poison, because a pending
  // record's createdAt can exceed a resolution the dead live stream never delivered, hiding it
  // from every future replay.
  if (key !== undefined && store.snapshot.status === 'ready' && store.subscription !== null &&
      store.lastChanged) {
    watermarks.set(key, store.lastChanged)
  }
  resetSession(store)
  store.subscription?.[Symbol.dispose]()
  store.subscription = null
}

function acquire(overseer: RpcStub<Overseer>): Store {
  const store = getStore(overseer)
  store.refCount++
  if (store.refCount === 1) {
    openSubscription(overseer, store)
  }
  return store
}

function release(overseer: RpcStub<Overseer>) {
  const store = stores.get(overseer)
  if (!store) return
  store.refCount--
  if (store.refCount <= 0) {
    closeSubscription(overseer, store)
    stores.delete(overseer)
  }
}

/** Subscribe to the gadget's action log. Pass `null` to no-op ('checking', empty maps). */
export function useActions(overseer: RpcStub<Overseer> | null): ActionsState {
  useEffect(() => {
    if (!overseer) return
    acquire(overseer)
    return () => release(overseer)
  }, [overseer])

  const subscribe = useCallback((cb: () => void) => {
    if (!overseer) return () => {}
    const store = getStore(overseer)
    store.listeners.add(cb)
    return () => { store.listeners.delete(cb) }
  }, [overseer])
  const getSnapshot = useCallback(() => {
    if (!overseer) return EMPTY_STATE
    return stores.get(overseer)?.snapshot ?? EMPTY_STATE
  }, [overseer])

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/**
 * Per-entry callback variant. Fires once per entry delivered on the live subscription (paged
 * pending records are not entries); on mount it replays the records already received this
 * session. That covers patching content fetched over the same stub: anything fetched reflects
 * the log at fetch time, and everything that changed since arrived through the stream.
 */
export function useActionEntries(
  overseer: RpcStub<Overseer> | null,
  onEntry: (record: ActionLogEntry) => void,
): void {
  const callbackRef = useRef(onEntry)
  callbackRef.current = onEntry

  useEffect(() => {
    if (!overseer) return

    function listener(record: ActionLogEntry): void {
      callbackRef.current(record)
    }

    const store = acquire(overseer)
    store.entryListeners.add(listener)

    // Retained until `release()` drops refCount to 0 and deletes the store, so late
    // consumers can replay already-received entries while a shared subscription is still alive.
    for (const record of store.stagedEntries.values()) {
      listener(record)
    }

    return () => {
      const s = stores.get(overseer)
      s?.entryListeners.delete(listener)
      release(overseer)
    }
  }, [overseer])
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { RpcStub } from 'capnweb'
import { matchesActionHistoryFilter } from '@gadgets/workshop-shared/api'
import type { ActionHistoryFilter, ActionLogEntry, Overseer } from '@gadgets/workshop-shared/api'
import { actionLogResumed, useActionEntries } from './useActions'

export type ActionHistoryStatus = 'loading' | 'ready' | 'error'

/**
 * The filters this hook pages: everything but "pending", whose live set is useActions' job. The
 * live-merge below leans on the exclusion — against the remaining filters a record never stops
 * matching (type never changes, and resolving only moves a record out of "pending"), so updates
 * failing the filter can be ignored rather than needing removal.
 */
export type HistoryViewFilter = Exclude<ActionHistoryFilter, 'pending'>

type HistoryState = {
  byId: ReadonlyMap<number, ActionLogEntry>
  // 'initial' = the first page failed (surfaces as status 'error'); 'more' = a loadMore failed.
  error: 'initial' | 'more' | null
}

type HistorySession = {
  frontier: number | undefined
  inFlight: boolean
  hasLoadedPage: boolean
}

function createHistorySession(): HistorySession {
  return { frontier: undefined, inFlight: false, hasLoadedPage: false }
}

const INITIAL: HistoryState = { byId: new Map(), error: null }

/**
 * Demand-loads action history (pending records included), one page at a time, newest first by id
 * (creation order). Nothing is fetched until `active` first becomes true; `loadMore()` continues
 * from the server cursor, and `hasMore` is the termination signal. The filter changing resets
 * everything; so does the overseer stub changing (a reconnect hands out a fresh stub), unless
 * the shared store resumed — then the loaded window and cursor survive the swap.
 *
 * Live updates from the shared action subscription are merged in: a filter-matching record —
 * a fresh pending one or a resolution — patches in place or inserts if it falls inside the
 * loaded id window. Records below the window are dropped — they surface, read fresh, when their
 * page loads.
 */
export function useActionHistory(
  overseer: RpcStub<Overseer> | null,
  filter: HistoryViewFilter,
  active: boolean,
) {
  const [state, setState] = useState<HistoryState>(INITIAL)
  // The request-identity token, mutated in place. `frontier` is undefined before the first page
  // and after the terminal page; `hasLoadedPage` distinguishes those states. The returned
  // status/hasMore/isLoadingMore are derived from it at the return site, which is safe because
  // every mutation of it is paired with a setState (so a render always follows).
  const sessionRef = useRef(createHistorySession())

  useEffect(() => {
    sessionRef.current = createHistorySession()
    setState(INITIAL)
  }, [filter])

  const loadMore = useCallback(() => {
    const session = sessionRef.current
    if (!overseer || session.inFlight ||
        (session.hasLoadedPage && session.frontier === undefined)) return
    const first = !session.hasLoadedPage
    session.inFlight = true
    setState(prev => ({ ...prev, error: null }))

    overseer.listActions({ beforeId: session.frontier, filter }).then(page => {
      if (sessionRef.current !== session) return
      session.inFlight = false
      session.hasLoadedPage = true
      session.frontier = page.nextBeforeId
      setState(prev => {
        const byId = new Map(prev.byId)
        for (const record of page.entries) byId.set(record.id, record)
        return { byId, error: null }
      })
    }, (err: unknown) => {
      if (sessionRef.current !== session) return
      session.inFlight = false
      console.error('Failed to load action history:', err)
      setState(prev => ({ ...prev, error: first ? 'initial' : 'more' }))
    })
  }, [overseer, filter])

  // Registered before the initial-load effect below: mounting the shared store initiates its
  // subscribeToActions, and effects run in declaration order, so capnweb e-order registers the
  // subscriber server-side before the first page's listActions reads (the subscribe-before-query
  // contract, see api.ts). Otherwise a record resolved between the two would be missed by both.
  useActionEntries(overseer, record => {
    const session = sessionRef.current
    // Dropping records here can't lose an update: listActions snapshots and responds in one DO
    // turn, so on the ordered RPC session an entry reflecting a post-snapshot change always
    // arrives after the page it would race with. Anything dropped pre-first-page or below the
    // frontier is state a loaded page already supersedes, or is read fresh when its page loads.
    if (!session.hasLoadedPage) return
    if (!matchesActionHistoryFilter(record, filter)) return
    if (session.frontier !== undefined && record.id < session.frontier) return
    setState(prev => {
      const byId = new Map(prev.byId)
      byId.set(record.id, record)
      return { ...prev, byId }
    })
  })

  // A stub swap resets everything — unless the shared store resumed, in which case the gap was
  // replayed through the subscription above: keep the window and the frontier (a server-stable
  // id cursor), rebuilding the session token so any in-flight old-stub page is dropped. Ordering
  // matters: after useActionEntries (which creates the store, setting its resumed flag), and
  // before the initial-load effect (so a reset refetches).
  const prevOverseerRef = useRef(overseer)
  useEffect(() => {
    if (prevOverseerRef.current === overseer) return
    prevOverseerRef.current = overseer
    if (actionLogResumed(overseer)) {
      const { frontier, hasLoadedPage } = sessionRef.current
      sessionRef.current = { frontier, inFlight: false, hasLoadedPage }
      setState(prev => ({ ...prev, error: null }))
    } else {
      sessionRef.current = createHistorySession()
      setState(INITIAL)
    }
  }, [overseer])

  useEffect(() => {
    if (active && !sessionRef.current.hasLoadedPage) loadMore()
  }, [active, loadMore])

  const entries = useMemo(
    () => Array.from(state.byId.values()).sort((a, b) => b.id - a.id),
    [state.byId])

  const session = sessionRef.current
  return {
    entries,
    // 'loading' from the start: nothing is fetched until `active`, but the panel isn't visible
    // (and the status unread) until then either, and the first fetch follows immediately.
    status: (state.error === 'initial' ? 'error'
        : session.hasLoadedPage ? 'ready' : 'loading') satisfies ActionHistoryStatus,
    hasMore: session.frontier !== undefined,
    isLoadingMore: session.inFlight && session.hasLoadedPage,
    loadMoreFailed: state.error === 'more',
    loadMore,
  }
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useKumoToastManager } from '@cloudflare/kumo'
import type { RpcStub } from 'capnweb'
import type { Overseer, PreApprovableAction } from '@gadgets/workshop-shared/api'
import type { ActionKind } from '@gadgets/workshop-shared/gatekeeper'

export interface AutoApprovalEntry {
  gatekeeperId: number
  resourceTitle: string
  vendorId?: string
  actionKind: ActionKind
  enabled: boolean
  /** Keep orphaned rules visible so a standing grant never becomes impossible to revoke. */
  orphaned: boolean
}

export function autoApprovalKey(entry: { gatekeeperId: number; actionKind: ActionKind }): string {
  return `${entry.gatekeeperId}:${entry.actionKind.tag}`
}

export function useAutoApproval(overseer: RpcStub<Overseer> | null) {
  const toasts = useKumoToastManager()
  const [catalog, setCatalog] = useState<PreApprovableAction[]>([])
  const [rules, setRules] = useState<Array<{ gatekeeperId: number; actionKind: ActionKind }>>([])
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [pending, setPending] = useState<Set<string>>(new Set())
  const refreshGeneration = useRef(0)

  const refresh = useCallback(async () => {
    const generation = ++refreshGeneration.current
    if (!overseer) {
      setCatalog([])
      setRules([])
      setLoadError(false)
      setIsLoading(false)
      return
    }

    const [catalogResult, rulesResult] = await Promise.allSettled([
      overseer.listPreApprovableActions(),
      overseer.listAutoApprovedActionKinds(),
    ])

    if (generation !== refreshGeneration.current) return

    let failed = false
    if (catalogResult.status === 'fulfilled') {
      setCatalog(catalogResult.value)
    } else {
      failed = true
      setCatalog([])
      console.error('Failed to load auto-approval catalog:', catalogResult.reason)
    }

    if (rulesResult.status === 'fulfilled') {
      setRules(rulesResult.value)
    } else {
      failed = true
      setRules([])
      console.error('Failed to load auto-approval rules:', rulesResult.reason)
    }

    setLoadError(failed)
    setIsLoading(false)
  }, [overseer])

  useEffect(() => {
    setIsLoading(true)
    void refresh()
  }, [refresh])

  const entries = useMemo((): AutoApprovalEntry[] => {
    const byKey = new Map<string, AutoApprovalEntry>()
    for (const action of catalog) {
      byKey.set(autoApprovalKey(action), {
        gatekeeperId: action.gatekeeperId,
        resourceTitle: action.resourceTitle,
        vendorId: action.vendorId,
        actionKind: action.actionKind,
        enabled: action.alreadyEnabled,
        orphaned: false,
      })
    }
    for (const rule of rules) {
      const key = autoApprovalKey(rule)
      const known = byKey.get(key)
      if (known) known.enabled = true
      else {
        byKey.set(key, {
          gatekeeperId: rule.gatekeeperId,
          resourceTitle: '',
          actionKind: rule.actionKind,
          enabled: true,
          orphaned: true,
        })
      }
    }
    return [...byKey.values()]
  }, [catalog, rules])

  const setEnabled = useCallback(async (entry: AutoApprovalEntry, enabled: boolean) => {
    if (!overseer) return
    const key = autoApprovalKey(entry)
    setPending(previous => new Set(previous).add(key))
    setCatalog(previous => previous.map(action =>
      autoApprovalKey(action) === key ? { ...action, alreadyEnabled: enabled } : action))
    setRules(previous => enabled
      ? [...previous, { gatekeeperId: entry.gatekeeperId, actionKind: entry.actionKind }]
      : previous.filter(rule => autoApprovalKey(rule) !== key))
    try {
      if (enabled) await overseer.setAutoApprovedActionKind(entry.gatekeeperId, entry.actionKind)
      else await overseer.removeAutoApprovedActionKind(entry.gatekeeperId, entry.actionKind.tag)
    } catch (err) {
      console.error('Failed to update auto-approval rule:', err)
      toasts.add({
        title: `Failed to ${enabled ? 'enable' : 'disable'} auto-approval`,
        variant: 'error',
      })
    } finally {
      await refresh()
      setPending(previous => {
        const next = new Set(previous)
        next.delete(key)
        return next
      })
    }
  }, [overseer, refresh, toasts])

  return { entries, isLoading, loadError, pending, refresh, setEnabled }
}

