          No gadgets yet
        </p>
        <p className="mt-1.5 mb-0 text-[13px] leading-[19px] tracking-[-0.25px] text-kumo-subtle">
          Ask the agent in chat to build something, and it will appear here.
        </p>
      </div>
    </div>
  )
}

