          overseer.listChats(),
          overseer.listModels(),
        ]);

        chats.forEach((chat) => {
          cacheRef.current.chats.set(chat.id, chat);
        });
        bumpChatListVersion();
        setChatListReady(true);

        setAvailableModels(models);

        setSelectedModel(getStoredSelectedModel(models));

        forceUpdate();
